<script setup lang="ts">function navigate(event: KeyboardEvent) { if (!['ArrowDown','ArrowUp','Home','End'].includes(event.key)) return; const menu = event.currentTarget as HTMLElement; const items = Array.from(menu.querySelectorAll<HTMLButtonElement>('[role=menuitem]:not(:disabled)')); if (!items.length) return; const index = items.indexOf(document.activeElement as HTMLButtonElement); const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : (index + (event.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length; event.preventDefault(); items[next]?.focus() }</script>
<template><ul class="ew-menu" role="menu" tabindex="-1" @keydown="navigate"><slot /></ul></template>
